static
void kernel_floyd_warshall(int n,
			   DATA_TYPE POLYBENCH_2D(path,N,N,n,n))
{
  int i, j, k;

#pragma scop
  for (k = 0; k < _PB_N; k++)
    {
      for(i = 0; i < _PB_N; i++)
	{
	  DATA_TYPE pik = path[i][k];
	  int j = 0;

	  for (; j < _PB_N; )
	    {
	      size_t vl = __riscv_vsetvl_e32m8((size_t)(_PB_N - j));

	      vint32m8_t vpath = __riscv_vle32_v_i32m8((const int32_t *)&path[i][j], vl);
	      vint32m8_t vk = __riscv_vle32_v_i32m8((const int32_t *)&path[k][j], vl);
	      vint32m8_t vsum = __riscv_vadd_vx_i32m8(vk, (int32_t)pik, vl);
	      vint32m8_t vmin = __riscv_vmin_vv_i32m8(vpath, vsum, vl);

	      __riscv_vse32_v_i32m8((int32_t *)&path[i][j], vmin, vl);
	      j += (int)vl;
	    }
	  }
    }
#pragma endscop

}

