static
void kernel_gemver(int n,
		   DATA_TYPE alpha,
		   DATA_TYPE beta,
		   DATA_TYPE POLYBENCH_2D(A,N,N,n,n),
		   DATA_TYPE POLYBENCH_1D(u1,N,n),
		   DATA_TYPE POLYBENCH_1D(v1,N,n),
		   DATA_TYPE POLYBENCH_1D(u2,N,n),
		   DATA_TYPE POLYBENCH_1D(v2,N,n),
		   DATA_TYPE POLYBENCH_1D(w,N,n),
		   DATA_TYPE POLYBENCH_1D(x,N,n),
		   DATA_TYPE POLYBENCH_1D(y,N,n),
		   DATA_TYPE POLYBENCH_1D(z,N,n))
{
  int i, j;

#pragma scop

  for (i = 0; i < _PB_N; i++) {
    int j = 0;
    for (; j + 3 < _PB_N; j += 4) {
      A[i][j]     = A[i][j]     + u1[i] * v1[j]     + u2[i] * v2[j];
      A[i][j + 1] = A[i][j + 1] + u1[i] * v1[j + 1] + u2[i] * v2[j + 1];
      A[i][j + 2] = A[i][j + 2] + u1[i] * v1[j + 2] + u2[i] * v2[j + 2];
      A[i][j + 3] = A[i][j + 3] + u1[i] * v1[j + 3] + u2[i] * v2[j + 3];
    }
    for (; j < _PB_N; j++) {
      A[i][j] = A[i][j] + u1[i] * v1[j] + u2[i] * v2[j];
    }
  }

  for (i = 0; i < _PB_N; i++) {
    int j = 0;
    for (; j + 3 < _PB_N; j += 4) {
      x[i] = x[i] + beta * A[j][i] * y[j];
      x[i] = x[i] + beta * A[j + 1][i] * y[j + 1];
      x[i] = x[i] + beta * A[j + 2][i] * y[j + 2];
      x[i] = x[i] + beta * A[j + 3][i] * y[j + 3];
    }
    for (; j < _PB_N; j++) {
      x[i] = x[i] + beta * A[j][i] * y[j];
    }
  }

  for (i = 0; i < _PB_N; i++) {
    x[i] = x[i] + z[i];
  }

  for (i = 0; i < _PB_N; i++) {
    int j = 0;
    for (; j + 3 < _PB_N; j += 4) {
      w[i] = w[i] +  alpha * A[i][j] * x[j];
      w[i] = w[i] +  alpha * A[i][j + 1] * x[j + 1];
      w[i] = w[i] +  alpha * A[i][j + 2] * x[j + 2];
      w[i] = w[i] +  alpha * A[i][j + 3] * x[j + 3];
    }
    for (; j < _PB_N; j++) {
      w[i] = w[i] +  alpha * A[i][j] * x[j];
    }
  }

#pragma endscop
}

