static
void kernel_gesummv(int n,
		    DATA_TYPE alpha,
		    DATA_TYPE beta,
		    DATA_TYPE POLYBENCH_2D(A,N,N,n,n),
		    DATA_TYPE POLYBENCH_2D(B,N,N,n,n),
		    DATA_TYPE POLYBENCH_1D(tmp,N,n),
		    DATA_TYPE POLYBENCH_1D(x,N,n),
		    DATA_TYPE POLYBENCH_1D(y,N,n))
{
  int i, j;

#pragma scop
  for (i = 0; i < _PB_N; i++)
    {
      tmp[i] = SCALAR_VAL(0.0);
      y[i] = SCALAR_VAL(0.0);

      int j0 = 0;
      for (; j0 < _PB_N; )
        {
          size_t vl = __riscv_vsetvl_e64m1((size_t)(_PB_N - j0));

          vfloat64m1_t vx = __riscv_vle64_v_f64m1(&x[j0], vl);
          vfloat64m1_t va = __riscv_vle64_v_f64m1(&A[i][j0], vl);
          vfloat64m1_t vb = __riscv_vle64_v_f64m1(&B[i][j0], vl);

          vfloat64m1_t vtmp = __riscv_vfmv_v_f_f64m1(tmp[i], vl);
          vfloat64m1_t vy = __riscv_vfmv_v_f_f64m1(y[i], vl);

          vtmp = __riscv_vfmacc_vv_f64m1(vtmp, va, vx, vl);
          vy = __riscv_vfmacc_vv_f64m1(vy, vb, vx, vl);

          tmp[i] = __riscv_vfmv_f_s_f64m1_f64(vtmp);
          y[i] = __riscv_vfmv_f_s_f64m1_f64(vy);

          j0 += (int)vl;
        }

      y[i] = alpha * tmp[i] + beta * y[i];
    }
#pragma endscop

}

