static
void kernel_heat_3d(int tsteps,
		      int n,
		      DATA_TYPE POLYBENCH_3D(A,N,N,N,n,n,n),
		      DATA_TYPE POLYBENCH_3D(B,N,N,N,n,n,n))
{
  int t, i, j, k;
  const int lim = _PB_N - 1;
  const DATA_TYPE c1 = SCALAR_VAL(0.125);
  const DATA_TYPE c2 = SCALAR_VAL(2.0);

#pragma scop
  for (t = 1; t <= TSTEPS; t++) {
    for (i = 1; i < lim; i++) {
      for (j = 1; j < lim; j++) {
        k = 1;
        for (; k < lim; ) {
          size_t vl = __riscv_vsetvl_e64m1((size_t)(lim - k));

          vfloat64m1_t a_ij = __riscv_vle64_v_f64m1(&A[i][j][k], vl);
          vfloat64m1_t a_ip1 = __riscv_vle64_v_f64m1(&A[i + 1][j][k], vl);
          vfloat64m1_t a_im1 = __riscv_vle64_v_f64m1(&A[i - 1][j][k], vl);
          vfloat64m1_t a_jp1 = __riscv_vle64_v_f64m1(&A[i][j + 1][k], vl);
          vfloat64m1_t a_jm1 = __riscv_vle64_v_f64m1(&A[i][j - 1][k], vl);
          vfloat64m1_t a_kp1 = __riscv_vle64_v_f64m1(&A[i][j][k + 1], vl);
          vfloat64m1_t a_km1 = __riscv_vle64_v_f64m1(&A[i][j][k - 1], vl);

          vfloat64m1_t tmp = __riscv_vfsub_vv_f64m1(a_ip1, __riscv_vfmul_vf_f64m1(a_ij, c2, vl), vl);
          tmp = __riscv_vfadd_vv_f64m1(tmp, a_im1, vl);
          tmp = __riscv_vfmul_vf_f64m1(tmp, c1, vl);

          vfloat64m1_t tmp2 = __riscv_vfsub_vv_f64m1(a_jp1, __riscv_vfmul_vf_f64m1(a_ij, c2, vl), vl);
          tmp2 = __riscv_vfadd_vv_f64m1(tmp2, a_jm1, vl);
          tmp2 = __riscv_vfmul_vf_f64m1(tmp2, c1, vl);

          vfloat64m1_t tmp3 = __riscv_vfsub_vv_f64m1(a_kp1, __riscv_vfmul_vf_f64m1(a_ij, c2, vl), vl);
          tmp3 = __riscv_vfadd_vv_f64m1(tmp3, a_km1, vl);
          tmp3 = __riscv_vfmul_vf_f64m1(tmp3, c1, vl);

          vfloat64m1_t res = __riscv_vfadd_vv_f64m1(tmp, tmp2, vl);
          res = __riscv_vfadd_vv_f64m1(res, tmp3, vl);
          res = __riscv_vfadd_vv_f64m1(res, a_ij, vl);

          __riscv_vse64_v_f64m1(&B[i][j][k], res, vl);
          k += (int)vl;
        }
      }
    }
    for (i = 1; i < lim; i++) {
      for (j = 1; j < lim; j++) {
        k = 1;
        for (; k < lim; ) {
          size_t vl = __riscv_vsetvl_e64m1((size_t)(lim - k));

          vfloat64m1_t b_ij = __riscv_vle64_v_f64m1(&B[i][j][k], vl);
          vfloat64m1_t b_ip1 = __riscv_vle64_v_f64m1(&B[i + 1][j][k], vl);
          vfloat64m1_t b_im1 = __riscv_vle64_v_f64m1(&B[i - 1][j][k], vl);
          vfloat64m1_t b_jp1 = __riscv_vle64_v_f64m1(&B[i][j + 1][k], vl);
          vfloat64m1_t b_jm1 = __riscv_vle64_v_f64m1(&B[i][j - 1][k], vl);
          vfloat64m1_t b_kp1 = __riscv_vle64_v_f64m1(&B[i][j][k + 1], vl);
          vfloat64m1_t b_km1 = __riscv_vle64_v_f64m1(&B[i][j][k - 1], vl);

          vfloat64m1_t tmp = __riscv_vfsub_vv_f64m1(b_ip1, __riscv_vfmul_vf_f64m1(b_ij, c2, vl), vl);
          tmp = __riscv_vfadd_vv_f64m1(tmp, b_im1, vl);
          tmp = __riscv_vfmul_vf_f64m1(tmp, c1, vl);

          vfloat64m1_t tmp2 = __riscv_vfsub_vv_f64m1(b_jp1, __riscv_vfmul_vf_f64m1(b_ij, c2, vl), vl);
          tmp2 = __riscv_vfadd_vv_f64m1(tmp2, b_jm1, vl);
          tmp2 = __riscv_vfmul_vf_f64m1(tmp2, c1, vl);

          vfloat64m1_t tmp3 = __riscv_vfsub_vv_f64m1(b_kp1, __riscv_vfmul_vf_f64m1(b_ij, c2, vl), vl);
          tmp3 = __riscv_vfadd_vv_f64m1(tmp3, b_km1, vl);
          tmp3 = __riscv_vfmul_vf_f64m1(tmp3, c1, vl);

          vfloat64m1_t res = __riscv_vfadd_vv_f64m1(tmp, tmp2, vl);
          res = __riscv_vfadd_vv_f64m1(res, tmp3, vl);
          res = __riscv_vfadd_vv_f64m1(res, b_ij, vl);

          __riscv_vse64_v_f64m1(&A[i][j][k], res, vl);
          k += (int)vl;
        }
      }
    }
  }
#pragma endscop
}

