static
void kernel_mvt(int n,
		DATA_TYPE POLYBENCH_1D(x1,N,n),
		DATA_TYPE POLYBENCH_1D(x2,N,n),
		DATA_TYPE POLYBENCH_1D(y_1,N,n),
		DATA_TYPE POLYBENCH_1D(y_2,N,n),
		DATA_TYPE POLYBENCH_2D(A,N,N,n,n))
{
  int i, j;

#pragma scop
  for (i = 0; i < _PB_N; i++) {
    DATA_TYPE acc1 = x1[i];
    int j1 = 0;
    for (; j1 + 3 < _PB_N; j1 += 4) {
      acc1 += A[i][j1]     * y_1[j1];
      acc1 += A[i][j1 + 1] * y_1[j1 + 1];
      acc1 += A[i][j1 + 2] * y_1[j1 + 2];
      acc1 += A[i][j1 + 3] * y_1[j1 + 3];
    }
    for (; j1 < _PB_N; j1++) {
      acc1 += A[i][j1] * y_1[j1];
    }
    x1[i] = acc1;
  }

  for (i = 0; i < _PB_N; i++) {
    DATA_TYPE acc2 = x2[i];
    int j2 = 0;
    for (; j2 + 3 < _PB_N; j2 += 4) {
      acc2 += A[j2]     [i] * y_2[j2];
      acc2 += A[j2 + 1] [i] * y_2[j2 + 1];
      acc2 += A[j2 + 2] [i] * y_2[j2 + 2];
      acc2 += A[j2 + 3] [i] * y_2[j2 + 3];
    }
    for (; j2 < _PB_N; j2++) {
      acc2 += A[j2][i] * y_2[j2];
    }
    x2[i] = acc2;
  }
#pragma endscop
}

