static
void kernel_nussinov(int n, base POLYBENCH_1D(seq,N,n),
			   DATA_TYPE POLYBENCH_2D(table,N,N,n,n))
{
  int i, j, k;

#pragma scop
  for (i = _PB_N - 1; i >= 0; i--) {
    for (j = i + 1; j < _PB_N; j++) {
      DATA_TYPE best = table[i][j];

      if (j - 1 >= 0)
        best = max_score(best, table[i][j - 1]);
      if (i + 1 < _PB_N)
        best = max_score(best, table[i + 1][j]);

      if (j - 1 >= 0 && i + 1 < _PB_N) {
        if (i < j - 1)
          best = max_score(best, table[i + 1][j - 1] + match(seq[i], seq[j]));
        else
          best = max_score(best, table[i + 1][j - 1]);
      }

      for (k = i + 1; k < j; k++) {
        best = max_score(best, table[i][k] + table[k + 1][j]);
      }

      table[i][j] = best;
    }
  }
#pragma endscop
}

