static
void kernel_seidel_2d(int tsteps,
		      int n,
		      DATA_TYPE POLYBENCH_2D(A,N,N,n,n))
{
  int t, i, j;
  const int nn = n;
  const DATA_TYPE inv9 = (DATA_TYPE)1.0 / 9.0;

#pragma scop
  for (t = 0; t <= _PB_TSTEPS - 1; t++) {
    for (i = 1; i <= nn - 2; i++) {
      int j = 1;
      for (; j <= nn - 2; ) {
        size_t vl = __riscv_vsetvl_e64m1((size_t)(nn - 1 - j));

        vfloat64m1_t v_upm1 = __riscv_vle64_v_f64m1(&A[i - 1][j - 1], vl);
        vfloat64m1_t v_up   = __riscv_vle64_v_f64m1(&A[i - 1][j], vl);
        vfloat64m1_t v_up1  = __riscv_vle64_v_f64m1(&A[i - 1][j + 1], vl);

        vfloat64m1_t v_midm1 = __riscv_vle64_v_f64m1(&A[i][j - 1], vl);
        vfloat64m1_t v_mid   = __riscv_vle64_v_f64m1(&A[i][j], vl);
        vfloat64m1_t v_mid1  = __riscv_vle64_v_f64m1(&A[i][j + 1], vl);

        vfloat64m1_t v_dnm1  = __riscv_vle64_v_f64m1(&A[i + 1][j - 1], vl);
        vfloat64m1_t v_dn   = __riscv_vle64_v_f64m1(&A[i + 1][j], vl);
        vfloat64m1_t v_dn1   = __riscv_vle64_v_f64m1(&A[i + 1][j + 1], vl);

        vfloat64m1_t v_sum = __riscv_vfadd_vv_f64m1(v_upm1, v_up, vl);
        v_sum = __riscv_vfadd_vv_f64m1(v_sum, v_up1, vl);
        v_sum = __riscv_vfadd_vv_f64m1(v_sum, v_midm1, vl);
        v_sum = __riscv_vfadd_vv_f64m1(v_sum, v_mid, vl);
        v_sum = __riscv_vfadd_vv_f64m1(v_sum, v_mid1, vl);
        v_sum = __riscv_vfadd_vv_f64m1(v_sum, v_dnm1, vl);
        v_sum = __riscv_vfadd_vv_f64m1(v_sum, v_dn, vl);
        v_sum = __riscv_vfadd_vv_f64m1(v_sum, v_dn1, vl);

        v_sum = __riscv_vfmul_vf_f64m1(v_sum, inv9, vl);
        __riscv_vse64_v_f64m1(&A[i][j], v_sum, vl);

        j += (int)vl;
      }
    }
  }
#pragma endscop
}

