		 DATA_TYPE POLYBENCH_2D(C,M,N,m,n),
		 DATA_TYPE POLYBENCH_2D(A,M,M,m,m),
		 DATA_TYPE POLYBENCH_2D(B,M,N,m,n))
{
  int i, j, k;
  DATA_TYPE temp2;

#pragma scop
  for (i = 0; i < _PB_M; i++)
  {
    const DATA_TYPE ai = A[i][i];
    const DATA_TYPE alpha_ai = alpha * ai;

    for (j = 0; j < _PB_N; j++)
    {
      temp2 = 0;
      const DATA_TYPE bij = B[i][j];
      const DATA_TYPE alpha_bij = alpha * bij;

      for (k = 0; k < i; k++)
      {
        C[k][j] += alpha_bij * A[i][k];
        temp2 += B[k][j] * A[i][k];
      }

      C[i][j] = beta * C[i][j] + alpha_ai * bij + alpha * temp2;
    }
  }
#pragma endscop
}

#include <riscv_vector.h>

static
void kernel_syr2k(int n, int m,
		  DATA_TYPE alpha,
		  DATA_TYPE beta,
		  DATA_TYPE POLYBENCH_2D(C,N,N,n,n),
		  DATA_TYPE POLYBENCH_2D(A,N,M,n,m),
		  DATA_TYPE POLYBENCH_2D(B,N,M,n,m))
{
  int i, j, k;

#pragma scop
  for (i = 0; i < _PB_N; i++) {
    for (j = 0; j <= i; j++)
      C[i][j] *= beta;

    for (k = 0; k < _PB_M; k++) {
      const DATA_TYPE aik = A[i][k];
      const DATA_TYPE bik = B[i][k];

      int j = 0;
      for (; j <= i; ) {
        size_t vl = __riscv_vsetvl_e64m1((size_t)(i - j + 1));

        vfloat64m1_t vc = __riscv_vle64_v_f64m1(&C[i][j], vl);
        vfloat64m1_t va = __riscv_vle64_v_f64m1(&A[j][k], vl);
        vfloat64m1_t vb = __riscv_vle64_v_f64m1(&B[j][k], vl);

        vfloat64m1_t vtmp1 = __riscv_vfmul_vf_f64m1(va, alpha * bik, vl);
        vfloat64m1_t vtmp2 = __riscv_vfmul_vf_f64m1(vb, alpha * aik, vl);
        vc = __riscv_vfadd_vv_f64m1(vc, vtmp1, vl);
        vc = __riscv_vfadd_vv_f64m1(vc, vtmp2, vl);

        __riscv_vse64_v_f64m1(&C[i][j], vc, vl);
        j += (int)vl;
      }
    }
  }
#pragma endscop

}

#include <riscv_vector.h>

static
void kernel_syrk(int n, int m,
		 DATA_TYPE alpha,
		 DATA_TYPE beta,
		 DATA_TYPE POLYBENCH_2D(C,N,N,n,n),
		 DATA_TYPE POLYBENCH_2D(A,N,M,n,m))
{
  int i, j, k;

#pragma scop
  for (i = 0; i < _PB_N; i++) {
    for (j = 0; j <= i; j++)
      C[i][j] *= beta;

    for (k = 0; k < _PB_M; k++) {
      const DATA_TYPE aik = A[i][k];
      for (j = 0; j <= i; j++)
        C[i][j] += alpha * aik * A[j][k];
    }
  }
#pragma endscop

}

#include <riscv_vector.h>

static
void kernel_trisolv(int n,
		    DATA_TYPE POLYBENCH_2D(L,N,N,n,n),
		    DATA_TYPE POLYBENCH_1D(x,N,n),
		    DATA_TYPE POLYBENCH_1D(b,N,n))
{
  int i, j;

#pragma scop
  for (i = 0; i < _PB_N; i++)
    {
      x[i] = b[i];
      for (j = 0; j < i; j++)
        x[i] -= L[i][j] * x[j];
      x[i] = x[i] / L[i][i];
    }
#pragma endscop

}

#include <riscv_vector.h>

static
void kernel_trmm(int m, int n,
		 DATA_TYPE alpha,
		 DATA_TYPE POLYBENCH_2D(A,M,M,m,m),
		 DATA_TYPE POLYBENCH_2D(B,M,N,m,n))
{
  int i, j, k;

#pragma scop
  for (i = 0; i < _PB_M; i++) {
    for (j = 0; j < _PB_N; j++) {
      DATA_TYPE acc = B[i][j];
      for (k = i + 1; k < _PB_M; k++) {
        acc += A[k][i] * B[k][j];
      }
      B[i][j] = alpha * acc;
    }
  }
#pragma endscop
}
